const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "// ==============================================================================\n// DSL Stationery E-Commerce — Production Database Schema\n// Engine: PostgreSQL 18.4 (dsl_stationery)\n// ==============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ------------------------------------------------------------------------------\n// ENUMS\n// ------------------------------------------------------------------------------\n\nenum UserRole {\n  CUSTOMER\n  STAFF\n  MANAGER\n  ADMIN\n}\n\nenum OrderStatus {\n  PENDING\n  CONFIRMED\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  CANCELLED\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n}\n\nenum PaymentMethod {\n  CASH_ON_DELIVERY\n  BANK_TRANSFER\n  CARD_PAYHERE\n  KOKO_BNPL\n}\n\nenum DiscountType {\n  PERCENTAGE\n  FIXED_AMOUNT\n}\n\nenum InventoryChangeReason {\n  RESTOCK\n  CORRECTION\n  DAMAGED\n  ORDER_FULFILLMENT\n  DEMO_RESET\n}\n\nenum DocumentStatus {\n  UPLOADED\n  PROCESSING\n  PROCESSED\n  REVIEWED\n  CONVERTED_TO_CART\n}\n\nenum ItemConfidence {\n  HIGH\n  MEDIUM\n  LOW\n}\n\nenum MatchStatus {\n  MATCHED\n  UNMATCHED\n  CUSTOM_SELECTED\n  SKIPPED\n}\n\n// ------------------------------------------------------------------------------\n// USERS & ADDRESSES\n// ------------------------------------------------------------------------------\n\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  phone        String?\n  name         String\n  role         UserRole @default(CUSTOMER)\n  passwordHash String?\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  // Brute-force protection\n  failedLoginAttempts Int       @default(0)\n  lockedUntil         DateTime?\n\n  // Password reset (stores only a SHA-256 hash — never the raw token)\n  passwordResetTokenHash String?\n  passwordResetExpiresAt DateTime?\n\n  addresses     Address[]\n  orders        Order[]\n  wishlist      WishlistItem[]\n  savedLists    SavedStationeryList[]\n  documents     UploadedDocument[]\n  auditLogs     AuditLog[]\n  refreshTokens RefreshToken[]\n\n  @@index([email])\n  @@index([phone])\n}\n\nmodel Address {\n  id           String   @id @default(cuid())\n  userId       String\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  fullName     String\n  phone        String\n  email        String\n  addressLine1 String\n  addressLine2 String?\n  city         String\n  district     String // One of 25 Sri Lanka districts\n  postalCode   String?\n  isDefault    Boolean  @default(false)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@index([userId])\n  @@index([district])\n}\n\n// ------------------------------------------------------------------------------\n// REFRESH TOKENS (Authentication Sessions)\n// ------------------------------------------------------------------------------\n\nmodel RefreshToken {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tokenHash String   @unique // SHA-256 of the raw refresh token — raw token is NEVER stored\n  isRevoked Boolean  @default(false)\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n  // Note: @unique on tokenHash already creates a B-tree unique index.\n  // A redundant @@index([tokenHash]) is intentionally omitted.\n\n  @@index([userId])\n  @@index([expiresAt])\n}\n\n// ------------------------------------------------------------------------------\n// CATALOG (CATEGORIES, BRANDS, PRODUCTS & VARIANTS)\n// ------------------------------------------------------------------------------\n\nmodel Category {\n  id           String   @id @default(cuid())\n  name         String\n  slug         String   @unique\n  description  String\n  iconName     String?\n  image        String?\n  featured     Boolean  @default(false)\n  displayOrder Int      @default(0)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  products Product[]\n\n  @@index([slug])\n  @@index([featured])\n}\n\nmodel Brand {\n  id            String   @id @default(cuid())\n  name          String\n  slug          String   @unique\n  description   String\n  logo          String?\n  originCountry String\n  featured      Boolean  @default(false)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  products Product[]\n\n  @@index([slug])\n}\n\nmodel Product {\n  id                  String   @id @default(cuid())\n  name                String\n  slug                String   @unique\n  sku                 String   @unique\n  barcode             String?  @unique\n  description         String\n  shortDescription    String\n  categoryId          String\n  category            Category @relation(fields: [categoryId], references: [id], onDelete: Restrict)\n  brandId             String\n  brand               Brand    @relation(fields: [brandId], references: [id], onDelete: Restrict)\n  priceCents          Int // Price in integer cents (e.g. 45000 = Rs. 450.00)\n  compareAtPriceCents Int?\n  costPriceCents      Int?\n  stockQuantity       Int      @default(0)\n  lowStockThreshold   Int      @default(5)\n  isActive            Boolean  @default(true)\n  isFeatured          Boolean  @default(false)\n  isNewArrival        Boolean  @default(false)\n  isBestSeller        Boolean  @default(false)\n  images              String[] @default([])\n  tags                String[] @default([]) // Keywords including Sinhala/Tamil\n  rating              Float    @default(5.0)\n  reviewCount         Int      @default(0)\n  specifications      Json     @default(\"{}\")\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  variants           ProductVariant[]\n  movements          InventoryMovement[]\n  orderItems         OrderItem[]\n  packItems          SchoolPackItem[]\n  matchedUploadItems ExtractedStationeryItem[]\n  wishlistItems      WishlistItem[]\n\n  @@index([slug])\n  @@index([sku])\n  @@index([categoryId])\n  @@index([brandId])\n  @@index([isActive])\n  @@index([priceCents])\n}\n\nmodel ProductVariant {\n  id                  String   @id @default(cuid())\n  productId           String\n  product             Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  name                String // e.g. \"Blue Ink / Single Line\"\n  sku                 String   @unique\n  priceCents          Int\n  compareAtPriceCents Int?\n  stockQuantity       Int      @default(0)\n  attributes          Json // { \"color\": \"Blue\", \"ruling\": \"Single Line\" }\n  isActive            Boolean  @default(true)\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  orderItems OrderItem[]\n  movements  InventoryMovement[]\n\n  @@index([productId])\n  @@index([sku])\n}\n\nmodel InventoryMovement {\n  id               String                @id @default(cuid())\n  productId        String\n  product          Product               @relation(fields: [productId], references: [id], onDelete: Cascade)\n  variantId        String?\n  variant          ProductVariant?       @relation(fields: [variantId], references: [id], onDelete: SetNull)\n  previousQuantity Int\n  newQuantity      Int\n  changeAmount     Int\n  reason           InventoryChangeReason\n  note             String?\n  performedById    String?\n  createdAt        DateTime              @default(now())\n\n  @@index([productId])\n  @@index([createdAt])\n}\n\n// ------------------------------------------------------------------------------\n// SCHOOL PACKS & BUNDLES\n// ------------------------------------------------------------------------------\n\nmodel SchoolPack {\n  id                String   @id @default(cuid())\n  name              String\n  slug              String   @unique\n  grade             String // e.g. \"Grade 1-2\", \"Grade 6-9\", \"O/L\"\n  tier              String // \"essential\", \"standard\", \"premium\"\n  description       String\n  savingsPercentage Int      @default(10)\n  totalPriceCents   Int\n  isActive          Boolean  @default(true)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  items SchoolPackItem[]\n\n  @@index([slug])\n  @@index([grade])\n}\n\nmodel SchoolPackItem {\n  id                   String     @id @default(cuid())\n  packId               String\n  pack                 SchoolPack @relation(fields: [packId], references: [id], onDelete: Cascade)\n  productId            String\n  product              Product    @relation(fields: [productId], references: [id], onDelete: Restrict)\n  defaultQuantity      Int        @default(1)\n  unitPriceCents       Int\n  substituteProductIds String[]   @default([])\n  createdAt            DateTime   @default(now())\n\n  @@index([packId])\n  @@index([productId])\n}\n\n// ------------------------------------------------------------------------------\n// ORDERS & IMMUTABLE SNAPSHOTS\n// ------------------------------------------------------------------------------\n\nmodel Order {\n  id                    String        @id @default(cuid())\n  orderNumber           String        @unique // e.g. \"DSL-2026-4891\"\n  userId                String?\n  user                  User?         @relation(fields: [userId], references: [id], onDelete: SetNull)\n  customerName          String\n  customerEmail         String\n  customerPhone         String\n  subtotalCents         Int\n  discountCents         Int           @default(0)\n  deliveryCents         Int           @default(0)\n  totalCents            Int\n  paymentMethod         PaymentMethod\n  paymentStatus         PaymentStatus @default(PENDING)\n  orderStatus           OrderStatus   @default(PENDING)\n  notes                 String?\n  trackingNumber        String?\n  estimatedDeliveryDate DateTime?\n  promotionId           String?\n  promotion             Promotion?    @relation(fields: [promotionId], references: [id], onDelete: SetNull)\n  createdAt             DateTime      @default(now())\n  updatedAt             DateTime      @updatedAt\n\n  addressSnapshot OrderAddressSnapshot?\n  items           OrderItem[]\n\n  @@index([orderNumber])\n  @@index([customerEmail])\n  @@index([customerPhone])\n  @@index([orderStatus])\n  @@index([createdAt])\n}\n\nmodel OrderAddressSnapshot {\n  id            String  @id @default(cuid())\n  orderId       String  @unique\n  order         Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  fullName      String\n  phone         String\n  email         String\n  addressLine1  String\n  addressLine2  String?\n  city          String\n  district      String // One of 25 Sri Lanka districts\n  postalCode    String?\n  deliveryNotes String?\n}\n\nmodel OrderItem {\n  id              String          @id @default(cuid())\n  orderId         String\n  order           Order           @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product         @relation(fields: [productId], references: [id], onDelete: Restrict)\n  variantId       String?\n  variant         ProductVariant? @relation(fields: [variantId], references: [id], onDelete: SetNull)\n  productName     String // Frozen name snapshot\n  variantName     String? // Frozen variant name snapshot\n  sku             String // Frozen SKU snapshot\n  unitPriceCents  Int // Frozen price snapshot at purchase time\n  quantity        Int\n  totalPriceCents Int // unitPriceCents * quantity\n  createdAt       DateTime        @default(now())\n\n  @@index([orderId])\n  @@index([productId])\n}\n\n// ------------------------------------------------------------------------------\n// PROMOTIONS & VOUCHERS\n// ------------------------------------------------------------------------------\n\nmodel Promotion {\n  id                  String       @id @default(cuid())\n  code                String       @unique\n  title               String\n  description         String\n  discountType        DiscountType\n  discountValue       Int // Percentage (e.g. 10) or Fixed Rupees\n  minOrderAmountCents Int?\n  maxDiscountCents    Int?\n  startDate           DateTime\n  endDate             DateTime\n  isActive            Boolean      @default(true)\n  usageLimit          Int?\n  usageCount          Int          @default(0)\n  createdAt           DateTime     @default(now())\n  updatedAt           DateTime     @updatedAt\n\n  orders Order[]\n\n  @@index([code])\n  @@index([isActive])\n}\n\n// ------------------------------------------------------------------------------\n// UPLOADED BOOKLIST DOCUMENTS & OCR EXTRACTIONS\n// ------------------------------------------------------------------------------\n\nmodel UploadedDocument {\n  id             String         @id @default(cuid())\n  userId         String?\n  user           User?          @relation(fields: [userId], references: [id], onDelete: SetNull)\n  fileName       String\n  fileUrl        String\n  fileSizeBytes  Int\n  fileType       String\n  status         DocumentStatus @default(UPLOADED)\n  isSimulatedOCR Boolean        @default(false)\n  customerNotes  String?\n  createdAt      DateTime       @default(now())\n  updatedAt      DateTime       @updatedAt\n\n  extractedItems ExtractedStationeryItem[]\n\n  @@index([userId])\n  @@index([status])\n}\n\nmodel ExtractedStationeryItem {\n  id                  String           @id @default(cuid())\n  documentId          String\n  document            UploadedDocument @relation(fields: [documentId], references: [id], onDelete: Cascade)\n  rawText             String\n  itemDescription     String\n  quantity            Int              @default(1)\n  confidence          ItemConfidence   @default(MEDIUM)\n  confidenceScore     Float            @default(0.8)\n  matchedProductId    String?\n  matchedProduct      Product?         @relation(fields: [matchedProductId], references: [id], onDelete: SetNull)\n  candidateProductIds String[]         @default([])\n  status              MatchStatus      @default(MATCHED)\n  createdAt           DateTime         @default(now())\n\n  @@index([documentId])\n  @@index([matchedProductId])\n}\n\n// ------------------------------------------------------------------------------\n// WISHLIST & SAVED LISTS\n// ------------------------------------------------------------------------------\n\nmodel WishlistItem {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n\n  @@unique([userId, productId])\n  @@index([userId])\n}\n\nmodel SavedStationeryList {\n  id             String   @id @default(cuid())\n  userId         String\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title          String\n  description    String?\n  itemProductIds String[] @default([])\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@index([userId])\n}\n\n// ------------------------------------------------------------------------------\n// AUDIT LOGS, BANNERS & STORE SETTINGS\n// ------------------------------------------------------------------------------\n\nmodel StoreBanner {\n  id              String   @id @default(cuid())\n  title           String\n  subtitle        String\n  ctaText         String\n  ctaLink         String\n  badgeText       String?\n  backgroundColor String   @default(\"#0066CC\")\n  textColor       String   @default(\"#FFFFFF\")\n  imageUrl        String?\n  isActive        Boolean  @default(true)\n  displayOrder    Int      @default(0)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@index([isActive])\n}\n\nmodel AuditLog {\n  id          String   @id @default(cuid())\n  action      String // e.g. \"INVENTORY_ADJUST\", \"ORDER_STATUS_UPDATE\"\n  entityType  String // \"product\", \"order\", \"promotion\", \"inventory\"\n  entityId    String\n  description String\n  userId      String?\n  user        User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  createdAt   DateTime @default(now())\n\n  @@index([entityType, entityId])\n  @@index([createdAt])\n}\n\nmodel StoreSettings {\n  id                         String   @id @default(\"default\")\n  flatDeliveryFeeCents       Int      @default(35000) // Rs. 350.00\n  freeDeliveryThresholdCents Int      @default(500000) // Rs. 5,000.00\n  hotlinePhone               String   @default(\"+94 11 200 9000\")\n  whatsappNumber             String   @default(\"+94 77 123 4567\")\n  contactEmail               String   @default(\"support@dslstationery.lk\")\n  codEnabled                 Boolean  @default(true)\n  bankTransferEnabled        Boolean  @default(true)\n  onlineCardEnabled          Boolean  @default(false)\n  updatedAt                  DateTime @updatedAt\n}\n"
}

